import React, { useState, useEffect } from 'react';
import { X, QrCode, ZoomIn, ZoomOut, Image as ImageIcon, Search, Table, Eye } from 'lucide-react';

const REFRIGERANTE_IMG_BASE64 = "data:image/jpeg;base64,";

const REFRIGERANTES_DATA = [
  { code: '740744000', name: 'REFRIGERANTE R744' },
  { code: '167019', name: 'REFRIGERANTE R422D' },
  { code: '167030', name: 'REFRIGERANTE R407C' },
  { code: '16036000', name: 'REFRIGERANTE R290' },
  { code: '31848000', name: 'REFRIGERANTE R407F' },
  { code: '35339000', name: 'REFRIGERANTE R410A' },
  { code: '40631000', name: 'REFRIGERANTE R449A' },
  { code: '51455000', name: 'REFRIGERANTE R448A' },
  { code: '57331037', name: 'REFRIGERANTE R404A REGENERADO' },
  { code: '57599000', name: 'REFRIGERANTE R452A' },
  { code: '740134100', name: 'REFRIGERANTE R134A' },
  { code: '740404100', name: 'REFRIGERANTE R404A REGENERADO' },
  { code: '504UTR644', name: 'REFRIGERANTE R507' },
  { code: '88402076', name: 'REFRIGERANTE R450A' },
  { code: '88402077', name: 'REFRIGERANTE R513 A' },
  { code: '48381096', name: 'REFRIGERANTE R422A' },
  { code: '88402078', name: 'REFRIGERANTE R442A' },
  { code: '69674000', name: 'REFRIGERANTE R427A' },
  { code: '88402079', name: 'REFRIGERANTE R453A' },
  { code: '89222044', name: 'REFRIGERANTE R32' }
];

export default function QrModal({ isOpen, onClose, title, imageSrc }) {
  const [zoomLevel, setZoomLevel] = useState(1);
  const [viewMode, setViewMode] = useState('image'); // 'image' | 'table'
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (isOpen) {
      setZoomLevel(1);
      setSearchQuery('');
    }
  }, [isOpen, title]);

  if (!isOpen) return null;

  const isRefrigerante = title && title.toUpperCase().includes('REFRIGERANTE');
  const isQr = title ? title.toLowerCase().includes('qr') : false;
  
  // Si es refrigerante, siempre usa el base64 integrado infalible
  const finalImageSrc = isRefrigerante ? REFRIGERANTE_IMG_BASE64 : imageSrc;

  const handleClose = () => {
    setZoomLevel(1);
    onClose();
  };

  const filteredRefrigerantes = REFRIGERANTES_DATA.filter(item => 
    item.code.toLowerCase().includes(searchQuery.toLowerCase()) || 
    item.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="fixed inset-0 z-50 bg-slate-950/85 backdrop-blur-md flex items-center justify-center p-2 sm:p-4 animate-in fade-in duration-150 overflow-y-auto">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl p-4 sm:p-6 max-w-lg w-full shadow-2xl space-y-3.5 text-center text-white relative max-h-[92vh] flex flex-col my-auto">
        
        {/* Botón Cerrar */}
        <button
          onClick={handleClose}
          className="absolute right-4 top-4 text-slate-400 hover:text-white p-1.5 rounded-xl hover:bg-slate-800 transition z-10"
          title="Cerrar"
        >
          <X className="w-5 h-5" />
        </button>

        {/* Header */}
        <div className="flex items-center justify-center space-x-2 text-sky-400 pt-1">
          {isQr ? <QrCode className="w-6 h-6" /> : <ImageIcon className="w-6 h-6 text-emerald-400" />}
          <h3 className="text-lg sm:text-xl font-bold text-white pr-6">{title}</h3>
        </div>

        {/* Pestañas de vista para Refrigerantes (Imagen vs Tabla) */}
        {isRefrigerante && (
          <div className="flex items-center justify-center gap-2 bg-slate-800/90 p-1 rounded-xl w-fit mx-auto text-xs border border-slate-700/80">
            <button
              onClick={() => setViewMode('image')}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg font-medium transition ${viewMode === 'image' ? 'bg-emerald-600 text-white shadow' : 'text-slate-400 hover:text-white'}`}
            >
              <Eye className="w-3.5 h-3.5" />
              <span>Ver Imagen</span>
            </button>
            <button
              onClick={() => setViewMode('table')}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg font-medium transition ${viewMode === 'table' ? 'bg-emerald-600 text-white shadow' : 'text-slate-400 hover:text-white'}`}
            >
              <Table className="w-3.5 h-3.5" />
              <span>Lista / Buscar</span>
            </button>
          </div>
        )}

        {/* Controles de Zoom para Imagen */}
        {viewMode === 'image' && (
          <div className="flex items-center justify-center gap-2 text-xs">
            <button
              onClick={() => setZoomLevel(prev => Math.min(prev + 0.5, 3))}
              className="inline-flex items-center space-x-1 bg-slate-800 hover:bg-slate-700 text-sky-300 font-medium px-3 py-1.5 rounded-lg border border-slate-700 transition active:scale-95"
              title="Aumentar tamaño"
            >
              <ZoomIn className="w-3.5 h-3.5" />
              <span>Ampliar</span>
            </button>

            {zoomLevel > 1 && (
              <>
                <button
                  onClick={() => setZoomLevel(prev => Math.max(prev - 0.5, 1))}
                  className="inline-flex items-center space-x-1 bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium px-2.5 py-1.5 rounded-lg border border-slate-700 transition active:scale-95"
                  title="Reducir tamaño"
                >
                  <ZoomOut className="w-3.5 h-3.5" />
                  <span>Reducir</span>
                </button>
                <button
                  onClick={() => setZoomLevel(1)}
                  className="inline-flex items-center space-x-1 bg-slate-800 hover:bg-slate-700 text-amber-300 font-medium px-2.5 py-1.5 rounded-lg border border-slate-700 transition active:scale-95"
                  title="Restablecer tamaño original"
                >
                  <span>100%</span>
                </button>
              </>
            )}
          </div>
        )}

        {/* Vista 1: Imagen con Scroll y Zoom */}
        {viewMode === 'image' ? (
          <div className="flex flex-col flex-1 min-h-0 space-y-1.5">
            <div className="bg-white p-2 sm:p-3 rounded-2xl shadow-inner border border-slate-200 overflow-auto max-h-[55vh] flex-1 touch-pan-x touch-pan-y">
              <div
                className="transition-all duration-150"
                style={{
                  width: zoomLevel === 1 ? '100%' : `${zoomLevel * 100}%`,
                  minWidth: zoomLevel === 1 ? '100%' : `${zoomLevel * 100}%`,
                  display: 'flex',
                  justifyContent: zoomLevel === 1 ? 'center' : 'flex-start',
                  alignItems: 'flex-start'
                }}
              >
                <img
                  src={finalImageSrc}
                  alt={title}
                  className={`rounded-lg select-none ${isQr && zoomLevel === 1 ? 'max-w-[260px] mx-auto' : 'w-full h-auto object-contain'}`}
                  style={{ touchAction: 'pan-x pan-y' }}
                />
              </div>
            </div>
            {zoomLevel > 1 && (
              <p className="text-[11px] text-slate-400 text-center select-none">
                👆 Desliza con el dedo para desplazarte por la imagen
              </p>
            )}
          </div>
        ) : (
          /* Vista 2: Tabla de Códigos con Buscador Rápido */
          <div className="bg-slate-800/80 rounded-2xl p-3 border border-slate-700 flex flex-col flex-1 max-h-[55vh] text-left space-y-2.5 overflow-hidden">
            <div className="relative">
              <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Buscar código o refrigerante (ej: 404, 744, R32)..."
                className="w-full pl-9 pr-3 py-1.5 text-xs bg-slate-900 border border-slate-700 rounded-lg text-white placeholder-slate-400 focus:outline-none focus:border-emerald-500"
              />
            </div>

            <div className="overflow-y-auto flex-1 divide-y divide-slate-700/60 pr-1">
              {filteredRefrigerantes.map((item, idx) => (
                <div key={idx} className="py-2 px-1 flex items-center justify-between text-xs hover:bg-slate-700/30 rounded transition">
                  <span className="font-mono font-bold text-emerald-400 bg-slate-900/80 px-2 py-1 rounded border border-slate-700">
                    {item.code}
                  </span>
                  <span className="text-slate-200 font-semibold">
                    {item.name}
                  </span>
                </div>
              ))}
              {filteredRefrigerantes.length === 0 && (
                <p className="text-center text-slate-400 py-6 text-xs">No se encontró ningún refrigerante con esa búsqueda.</p>
              )}
            </div>
          </div>
        )}

        <p className="text-xs text-slate-400">
          {isQr ? 'Acerque la cámara del teléfono o lector para escanear.' : '💡 Puedes pulsar en "Ampliar" o consultar la lista para buscar al instante.'}
        </p>

        {/* Botón Cerrar */}
        <div className="pt-1">
          <button
            onClick={handleClose}
            className="w-full py-2.5 bg-slate-800 hover:bg-slate-700 text-white font-semibold text-xs rounded-xl transition border border-slate-700 active:scale-98"
          >
            Cerrar
          </button>
        </div>

      </div>
    </div>
  );
}
